  {
    "name": "Primary CTA Button",
    "role": "Main conversion action (Download, View Plans)",
    "description": "backgroundColor=#5d5bd4, color=#ffffff, borderRadius=8px, padding=8px 16px, font: Segoe UI Variable Text 500 15px. Hover darkens to #424197. The 8px radius is a hard corner relative to the 24px card radius — buttons feel precise, not soft."
  },
  {
    "name": "Ghost Navigation Button",
    "role": "Outline-style secondary actions in the top nav (Descargar Teams, Iniciar sesión)",
    "description": "backgroundColor=transparent, color=#262626, border=1px solid transparent (visual separation via spacing only), borderRadius=0px, padding=16px 30px 16px 12px. Zero border radius — purely typographic with no frame."
  },
  {
    "name": "Underline Navigation Button",
    "role": "Active tab/section indicator in horizontal content nav",
    "description": "backgroundColor=transparent, color=#0e1726, borderBottom=2px solid #0e1726, borderRadius=0px, padding=0 0 32px 0. Bottom border only — tab indicator with generous 32px bottom padding to position the underline at baseline distance."
  },
  {
    "name": "Pill Secondary Button",
    "role": "Decorative or secondary CTA overlaid on hero visual areas",
    "description": "backgroundColor=transparent, color=#ffffff, borderRadius=200px, padding=16px. Full pill shape reserved for white-text variants appearing over imagery — the only element with >24px radius, creating maximum contrast with sharp-cornered primary buttons."
  },
  {
    "name": "Transparent Content Card",
    "role": "Layout grouping without visual separation",
    "description": "backgroundColor=transparent, borderRadius=0px, boxShadow=none, padding=0. Used for grid cells that rely on surrounding whitespace rather than a surface for grouping."
  },
  {
    "name": "Labeled Badge",
    "role": "Section category labels (NOTICIAS DESTACADAS, SOLUCIONES)",
    "description": "backgroundColor=transparent, color=#17253d, borderRadius=0px, padding=0. Uppercase tracking at +0.08em (letterSpacing=0.08em via Segoe UI Variable Text), weight 600, 12px. Zero-padding text label — no visual container, relying on tracking and weight for distinction."
  },
  {
    "name": "Surface Badge",
    "role": "Tag chips on cards and content metadata",
    "description": "backgroundColor=#fefefe, color=#17253d, borderRadius=8px, padding=4px 8px. White card-colored surface with same 8px radius as buttons — system-consistent without hierarchical confusion."
  },
  {
    "name": "Top Navigation Bar",
    "role": "Global site header with Microsoft logo, product name, and nav links",
    "description": "backgroundColor=#ffffff, height=54px, borderBottom=1px solid #bdc5d2. Product name 'Teams' in Segoe UI Variable Text 600 at 15px. Nav items at 14px weight 400 #262626 with dropdown chevrons. Right-side CTAs use Ghost and Primary Button styles."
  },
  {
    "name": "Horizontal Section Tab Nav",
    "role": "In-page content navigation (Noticias destacadas, Soluciones, Productos y servicios)",
    "description": "backgroundColor=#ffffff, borderBottom=1px solid #bdc5d2, height=56px. Active item uses Underline Navigation Button style. Right-aligned CTA button uses Primary CTA Button style at #5d5bd4."
  },
  {
    "name": "Hero Section",
    "role": "Full-width page opener with headline, body, CTA, and product visual",
    "description": "backgroundColor=#ffffff (with #fbf5fb lilac tint at far right). Headline: Segoe UI Variable Display 600 48px tracking −0.01em, color=#0e1726. Body: 16px 400 #616161. CTA: Primary CTA Button. Right half: 3D product screenshot floating on illustrated background — image is contained, not full-bleed."
  },
  {
    "name": "Article Preview Card",
    "role": "News and blog post previews in card grid",
    "description": "Uses Elevated Content Card as container. Image fills top of card with no padding, borderRadius=24px 24px 0 0 clipping. Title: Segoe UI Variable Text 600 20px #17253d. Body: 14px 400 #616161. Footer: 'Más información' link in Microsoft Blue (#0067b8) with right-arrow icon, 16px padding all sides."
  },
  {
    "name": "Floating Icon Bar",
    "role": "Fixed right-side quick-action icons (contact, mail, phone)",
    "description": "backgroundColor=#ffffff, borderRadius=24px 0 0 24px (left-side pill), boxShadow=rgba(0,0,0,0.12) 0px 0px 2px 0px, rgba(0,0,0,0.14) 0px 2px 4px 0px. Icon color #17253d. Positioned fixed right:0, vertically centered."
  }
